PROGRAM PRG_Conversion
VAR
    btnMarcha : BOOL;   // Botón de marcha (entrada)
    btnParo : BOOL;     // Botón de paro (entrada)
    motor : BOOL;       // Estado del motor (salida)
    lampara : BOOL;     // Estado de la lámpara (salida)
    T1 : TON;           // Temporizador TON
END_VAR

// Lógica de control del motor
IF (btnMarcha OR motor) AND NOT btnParo THEN
    motor := TRUE;
ELSE
    motor := FALSE;
END_IF;

// Configuración y ejecución del temporizador TON
T1(IN := motor, PT := T#10S);

// Control de la lámpara basado en el temporizador
lampara := T1.Q;

PROGRAM PRG_Conversion
VAR_INPUT
    btnMarcha : BOOL; // Contacto normalmente abierto para arranque
    btnParo : BOOL;   // Contacto normalmente cerrado para detención
END_VAR

VAR_OUTPUT
    motor : BOOL;     // Bobina del motor
    lampara : BOOL;   // Bobina de la lámpara
END_VAR

VAR
    T1 : TON;         // Temporizador de retardo a la conexión
END_VAR

// Rama 1: Circuito de auto-retención (enclavamiento) del motor
motor := (btnMarcha OR motor) AND NOT btnParo;

// Rama 2: El motor activa el temporizador TON con un preset de 10 segundos
T1(IN := motor, PT := T#10S);

// Rama 3: La salida del temporizador enciende la lámpara
lampara := T1.Q;

END_PROGRAM

PROGRAM PRG_Conversion
VAR
    btnMarcha, btnParo : BOOL;  // Entradas
    motor, lampara : BOOL;      // Salidas
    T1 : TON;                   // Temporizador de 10 segundos
END_VAR

// Rama 1: btnMarcha y motor en paralelo, en serie con btnParo, alimentan motor
motor := (btnMarcha OR motor) AND btnParo;

// Rama 2: motor alimenta el temporizador T1 con tiempo preestablecido de 10 segundos
IF motor THEN
    T1(IN := TRUE, PT := T#10S);
ELSE
    T1(IN := FALSE);
END_IF;

// Rama 3: T1.Q alimenta la bobina lampara
lampara := T1.Q;

